"use strict";document.addEventListener("DOMContentLoaded",() =>{const executeButton = document.getElementById("executeButton");const executionMessage = document.getElementById("execution-message");const outputMessage = document.getElementById("output-message");const spinner = document.getElementById("spinner");executeButton.addEventListener("click",async () =>{executionMessage.textContent = "Processing...";outputMessage.classList.add("hidden");executeButton.disabled = true;spinner.classList.remove("hidden");try{const response = await fetch("/api/rules_extraction",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({}),});if (!response.ok){const errorText = await response.text();throw new Error(errorText || `HTTP error! status:${response.status}`);}const data = await response.json();executionMessage.textContent = "Execution Success";outputMessage.textContent = JSON.stringify(data,null,2);outputMessage.classList.remove("hidden");window.app.showToast("Rules extracted successfully!");}catch (error){executionMessage.textContent = "Execution Failed";outputMessage.textContent = "";window.app.showToast( "Error extracting rules. Please try again.","error",);console.error("Error during execution:",error);}finally{executeButton.disabled = false;spinner.classList.add("hidden");}});});